vulnerable_code:
function renderComment(comment) {
  const box = document.getElementById("comments");
  // BAD: browser parses user text as HTML
  box.innerHTML += `<div class="comment">${comment}</div>`;
}

function loadProfile(user) {
  const area = document.getElementById("profile");
  // BAD: unsanitized URL fragment can contain script: or onerror= handlers
  area.innerHTML = user.bio;
}

secure_code:
function renderComment(comment) {
  const box = document.getElementById("comments");
  const el = document.createElement("div");
  el.className = "comment";
  // GOOD: textContent never parses HTML; user text stays text
  el.textContent = comment;
  box.appendChild(el);
}

function loadProfile(user) {
  const area = document.getElementById("profile");
  area.textContent = user.bio;
}
